  {"id": "bjcal-4f1a48a8befa", "name": "“历史记忆中的京奉铁路”专题展览", "category": "博物馆展览", "latitude": null, "longitude": null, "address": "中国铁道博物馆正阳门展馆", "suitable_for_people": ["一个人", "两个人", "一群人"], "suitable_duration": ["2-3小时", "半天", "一整天"], "district": "东城区", "venue": "中国铁道博物馆正阳门展馆", "start_date": "2024-05-18", "end_date": "待定", "published_at": null, "source": "北京市人民政府·城市日历", "source_url": "http://www.beijing.gov.cn/fwcj/calendar/bwgzl/6658189e81a0c418cb56d864.html", "collected_at": "2026-10-05T06:09:15", "updated_at": "2026-10-05T06:09:15", "description": "展览以馆藏珍品《京奉铁路》相册为基础，从中选取京奉铁路的机构、人物、沿线站房、桥梁、工厂和机车车辆等百余张老照片，配合其他相关馆藏文物，以期真实、生动地再现京奉铁路的原貌，为世人揭开这一段尘封百年的历史记忆。"},
  {"id": "bjcal-c947ee19685b", "name": "渎山大玉海展", "category": "游园活动", "latitude": null, "longitude": null, "address": "团城景区", "suitable_for_people": ["一个人", "两个人", "一群人"], "suitable_duration": ["2-3小时", "半天", "一整天"], "district": "西城区", "venue": "团城景区", "start_date": "长期", "end_date": "长期", "published_at": null, "source": "北京市人民政府·城市日历", "source_url": "http://www.beijing.gov.cn/fwcj/calendar/yyhd/665891d1a02c360a60320304.html", "collected_at": "2026-10-05T06:09:15", "updated_at": "2026-10-05T06:09:15", "description": "展览综合前人对渎山大玉海的各种研究资料，通过史料记载、科学检测数据，力求为大众呈现一个完整的、真实的渎山大玉海。"}
